package me.kright.gametools.pga3d

import scala.annotation.targetName
import me.kright.gametools.flatarray.FlatDoubleSerializer
import me.kright.gametools.mathutil.CanEqualWithEps


/**
 * A point in 3d space, stored in dual representation with human-friendly fields x, y, z and constant w = 1.
 *
 * Variable fields: x, y, z.
 * Constant fields: w = 1.0.
 * Basis blade coefficients: wyz = -x, wxz = y, wxy = -z, xyz = 1.0.
 *
 * Generated by pgaNdCodeGen (me.kright.gametools.pga.codegen.scalagen.pga3d.runScalaCodeGen).
 * Do not edit by hand: change the generator and re-run it.
 */
final case class Pga3dPoint(x: Double = 0.0,
                            y: Double = 0.0,
                            z: Double = 0.0) derives CanEqual, CanEqualWithEps, FlatDoubleSerializer:
  inline val w = 1.0

  inline def wyz: Double = -x

  inline def wxz: Double = y

  inline def wxy: Double = -z

  inline def xyz: Double = 1.0

  override def toString: String =
    s"Pga3dPoint(x = $x, y = $y, z = $z)"

  def dual: Pga3dPlane =
    Pga3dPlane(
      x = x,
      y = y,
      z = z,
      w = 1.0,
    )

  def weight: Pga3dVector =
    Pga3dVector(
      x = x,
      y = y,
      z = z,
    )

  def bulk: Pga3dPointCenter.type =
    Pga3dPointCenter

  @targetName("unaryMinus")
  def unary_- : Pga3dProjectivePoint =
    Pga3dProjectivePoint(
      x = -x,
      y = -y,
      z = -z,
      w = -1.0,
    )

  def reverse: Pga3dProjectivePoint =
    Pga3dProjectivePoint(
      x = -x,
      y = -y,
      z = -z,
      w = -1.0,
    )

  def antiReverse: Pga3dPoint =
    this

  def bulkNormSquare: Double = 1.0

  def bulkNorm: Double = 1.0

  def normalizedByBulk: Pga3dPoint = this

  def weightNormSquare: Double =
    (x * x + y * y + z * z)

  def weightNorm: Double =
    Math.sqrt(weightNormSquare)

  def normalizedByWeight =
    this / weightNorm

  def normSquare: Double =
    (1.0 + x * x + y * y + z * z)

  def norm: Double =
    Math.sqrt(normSquare)

  def normalizedByNorm =
    this / norm

  @targetName("times")
  def *(r: Double): Pga3dProjectivePoint =
    Pga3dProjectivePoint(
      x = r * x,
      y = r * y,
      z = r * z,
      w = r,
    )

  /** multiplies by the reciprocal: one division instead of one per component, at the cost of one extra rounding (~0.5 ulp) */
  @targetName("div")
  def /(r: Double): Pga3dProjectivePoint =
    this * (1.0 / r)

  infix def min(other: Pga3dPoint): Pga3dPoint =
    Pga3dPoint(math.min(x, other.x), math.min(y, other.y), math.min(z, other.z))

  infix def max(other: Pga3dPoint): Pga3dPoint =
    Pga3dPoint(math.max(x, other.x), math.max(y, other.y), math.max(z, other.z))

  def distanceTo(point: Pga3dPoint): Double =
    (this - point).norm

