  def +(r: Pga3dProjectivePoint): Pga3dProjectivePoint =
    Pga3dProjectivePoint(
      x = (r.x + x),
      y = (r.y + y),
      z = (r.z + z),
      w = (1.0 + r.w),
    )

  @targetName("minus")
  def -(r: Pga3dProjectivePoint): Pga3dProjectivePoint =
    Pga3dProjectivePoint(
      x = (x - r.x),
      y = (y - r.y),
      z = (z - r.z),
      w = (1.0 - r.w),
    )

  def madd(r: Pga3dProjectivePoint, mult: Double): Pga3dProjectivePoint =
    Pga3dProjectivePoint(
      x = (x + mult * r.x),
      y = (y + mult * r.y),
      z = (z + mult * r.z),
