   *   y = 0.0,
   *   z = 0.0,
   *   wx = 0.0,
   *   wy = 0.0,
   *   wz = 0.0,
   *   xy = 0.0,
   *   xz = 0.0,
   *   yz = 0.0,
   *   wxy = (line.xy * (line.xz * y - line.xy * z - line.yz * x) - line.wx * line.xz - line.wy * line.yz),
